patch:
diff --git a/repro/no-var-fix-reference-error.js b/repro/no-var-fix-reference-error.js
new file mode 100644
index 0000000..256c965
--- /dev/null
+++ b/repro/no-var-fix-reference-error.js
@@ -0,0 +1,53 @@
+"use strict";
+
+/*
+ * Check for the report "[no-var] Fix causes ReferenceError".
+ *
+ * Applies the `no-var` autofix to the reporter's code and runs the result.
+ * Exits non-zero if the fixed code throws a ReferenceError (the reported
+ * symptom), zero otherwise.
+ *
+ * Usage (from the repo root):
+ *   node repro/no-var-fix-reference-error.js                 # this checkout
+ *   node repro/no-var-fix-reference-error.js <eslint-dir>    # e.g. an installed eslint@9.37.0
+ */
+
+const path = require("node:path");
+const vm = require("node:vm");
+const assert = require("node:assert");
+
+const eslintDir = process.argv[2]
+	? path.resolve(process.argv[2])
+	: path.resolve(__dirname, "..");
+const { Linter } = require(eslintDir);
+
+const source = `export function a() {
+    console.log(o);
+    var o;
+    return o;
+}
+`;
+
+const linter = new Linter();
+const config = [{ rules: { "no-var": ["error"] } }];
+const { output } = linter.verifyAndFix(source, config);
+
+console.log(`eslint ${require(path.join(eslintDir, "package.json")).version}`);
+console.log("--- code after autofix ---");
+console.log(output);
+
+// Run the fixed code (minus `export`) the way the original would run.
+const sandbox = { console: { log() {} }, result: undefined };
+
+try {
+	vm.runInNewContext(
+		`${output.replace(/^export /u, "")}\nresult = a();`,
+		sandbox,
+	);
+} catch (error) {
+	assert.fail(
+		`autofixed code throws ${error.name}: ${error.message}\n` +
+			"(the original code runs without error)",
+	);
+}
+console.log("autofixed code runs without error");
